const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chiangMai = ee.Geometry.Point([98.9856, 18.7883]); // Chiang Mai, Thailand
  const bangkok = ee.Geometry.Point([100.5018, 13.7563]); // Bangkok, Thailand
  const startDate = '2024-03-01';
  const endDate = '2024-03-31';

  // 2. Data Acquisition & Check
  // Sentinel-5P is suitable for aerosol index.
  // The 'absorbing_aerosol_index' is a proxy for aerosol optical depth, especially for smoke/dust.
  // A higher value indicates more aerosols.
  let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .select(['absorbing_aerosol_index', 'qa_value'])
    .filterDate(startDate, endDate);

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Sentinel-5P images found for March 2024.");
    console.log("A: No");
    return;
  }
  console.log(`Image collection size: ${collectionSize}`);

  // 3. Processing
  // Mask out low-quality pixels. A QA value > 0.75 is recommended.
  const maskHighQuality = function(image) {
    return image.updateMask(image.select('qa_value').gt(0.75));
  };
  collection = collection.map(maskHighQuality);

  // Create a single mean image for the month
  const meanImage = collection.select('absorbing_aerosol_index').mean();

  // 4. Calculation
  const scale = 3000; // S5P has coarse resolution, a large scale is appropriate.
  const reducer = ee.Reducer.mean();

  const chiangMaiStats = meanImage.reduceRegion({
    reducer: reducer,
    geometry: chiangMai,
    scale: scale,
    maxPixels: 1e9
  });

  const bangkokStats = meanImage.reduceRegion({
    reducer: reducer,
    geometry: bangkok,
    scale: scale,
    maxPixels: 1e9
  });

  const chiangMaiAOD = chiangMaiStats.get('absorbing_aerosol_index').getInfo();
  const bangkokAOD = bangkokStats.get('absorbing_aerosol_index').getInfo();

  // 5. Validation & Final Answer
  if (chiangMaiAOD === null || bangkokAOD === null) {
      console.log(`Chiang Mai AOD: ${chiangMaiAOD}`);
      console.log(`Bangkok AOD: ${bangkokAOD}`);
      console.log("Could not calculate AOD for one or both locations after quality masking.");
      console.log("C2: No Valid Pixels");
      return;
  }

  console.log(`Chiang Mai Mean Aerosol Index: ${chiangMaiAOD.toFixed(4)}`);
  console.log(`Bangkok Mean Aerosol Index: ${bangkokAOD.toFixed(4)}`);

  if (chiangMaiAOD > bangkokAOD) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err.message || err);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
